import (
	"encoding/json"
	"errors"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"regexp"
	"strconv"
	"strings"
	"sync"
	"time"
)

// 台账错误。调用方可用 errors.Is 判断具体原因。
var (
	ErrNotFound          = errors.New("release: 未找到")
	ErrRecipeExists      = errors.New("release: 配方版本已登记，内容不可覆盖")
	ErrRecipeNotFound    = errors.New("release: 配方版本不存在")
	ErrBatchExists       = errors.New("release: 批次编号重复")
	ErrInvalidState      = errors.New("release: 当前状态不允许该操作")
	ErrInvalidQuantity   = errors.New("release: 数量不合法")
	ErrInvalidInput      = errors.New("release: 输入内容不合法")
	ErrDuplicateMaterial = errors.New("release: 同一版本内物料编号重复")
	ErrUnknownMaterial   = errors.New("release: 物料不属于该批次绑定的配方版本")
	ErrRequestConflict   = errors.New("release: 请求编号已被其他操作或不同内容占用")
	ErrCorruptData       = errors.New("release: 已有数据无法读取")
)

// BatchStatus 表示批次状态：草稿、执行中、已关闭。
type BatchStatus string

const (
	StatusDraft   BatchStatus = "draft"
	StatusRunning BatchStatus = "running"
	StatusClosed  BatchStatus = "closed"
)

// Grams 以毫克为单位精确保存克数，避免浮点误差。
type Grams int64

var gramsPattern = regexp.MustCompile(`^(0|[1-9][0-9]*)(\.[0-9]{1,3})?$`)

// ParseGrams 解析克数字符串，要求为正数且最多三位小数，如 "12.5"、"0.001"。
func ParseGrams(s string) (Grams, error) {
	if !gramsPattern.MatchString(s) {
		return 0, fmt.Errorf("%w: 克数 %q 需为正数且最多三位小数", ErrInvalidQuantity, s)
	}
	whole, frac, _ := strings.Cut(s, ".")
	if len(whole) > 15 {
		return 0, fmt.Errorf("%w: 克数 %q 超出可表示范围", ErrInvalidQuantity, s)
	}
	var mg int64
	for _, c := range whole {
		mg = mg*10 + int64(c-'0')
	}
	mg *= 1000
	frac += "000"
	for _, c := range frac[:3] {
		mg = mg*10 + int64(c-'0')
	}
	if mg <= 0 {
		return 0, fmt.Errorf("%w: 克数必须为正数", ErrInvalidQuantity)
	}
	return Grams(mg), nil
}

// String 以克为单位格式化，去掉多余的尾零。
func (g Grams) String() string {
	mg := int64(g)
	whole, frac := mg/1000, mg%1000
	if frac == 0 {
		return strconv.FormatInt(whole, 10)
	}
	s := strings.TrimRight(fmt.Sprintf("%03d", frac), "0")
	return strconv.FormatInt(whole, 10) + "." + s
}

// Material 是配方中的一种物料：物料编号和生产一份需要的克数。
type Material struct {
	MaterialID string
	Grams      Grams
}

// RecipeVersion 由配方编号和版本号共同识别的一个配方版本。
type RecipeVersion struct {
	RecipeID  string
	Version   string
	Name      string
	Materials []Material
}

// Feeding 是一条已登记的投料记录。
type Feeding struct {
	MaterialID string
	Grams      Grams
	FedAt      time.Time
	Operator   string
}

// MaterialReport 是查询批次时单个物料的数量核对。
type MaterialReport struct {
	MaterialID string
	Required   Grams // 应投量 = 单份克数 × 计划份数
	Actual     Grams // 累计实投量
	Diff       Grams // 实投减应投
}

// BatchReport 是按批次查询返回的完整记录。
type BatchReport struct {
	BatchID    string
	RecipeID   string
	Version    string
	RecipeName string
	Units      int
	Status     BatchStatus
	Feedings   []Feeding
	Materials  []MaterialReport
}

// 磁盘上的持久化结构。
type storedMaterial struct {
	MaterialID string `json:"materialId"`
	Milligrams int64  `json:"milligrams"`
}

type storedRecipe struct {
	RecipeID  string           `json:"recipeId"`
	Version   string           `json:"version"`
	Name      string           `json:"name"`
	Materials []storedMaterial `json:"materials"`
}

type feedingRecord struct {
	MaterialID string    `json:"materialId"`
	Milligrams int64     `json:"milligrams"`
	FedAt      time.Time `json:"fedAt"`
	Operator   string    `json:"operator"`
}

type batchRecord struct {
	BatchID  string          `json:"batchId"`
	RecipeID string          `json:"recipeId"`
	Version  string          `json:"version"`
	Units    int             `json:"units"`
	Status   BatchStatus     `json:"status"`
	Feedings []feedingRecord `json:"feedings"`
}

type diskState struct {
	Recipes  map[string]storedRecipe `json:"recipes"`
	Batches  map[string]*batchRecord `json:"batches"`
	Requests map[string]string       `json:"requests"` // 请求编号 -> 操作内容指纹
}

// Ledger 是位于某个本机数据位置的一本台账。
type Ledger struct {
	dir   string
	path  string
	mu    sync.Mutex
	state diskState
}

func recipeKey(recipeID, version string) string {
	return recipeID + "\x00" + version
}

// Open 打开指定数据位置的台账。位置为空或首次使用时得到空台账；
// 位置下已有数据但无法读取时返回 ErrCorruptData，绝不当作空台账继续。
func Open(dir string) (*Ledger, error) {
	if strings.TrimSpace(dir) == "" {
		return nil, fmt.Errorf("%w: 数据位置不能为空", ErrInvalidInput)
	}
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return nil, fmt.Errorf("%w: 无法创建数据位置 %s: %v", ErrCorruptData, dir, err)
	}
	l := &Ledger{
		dir:  dir,
		path: filepath.Join(dir, "ledger.json"),
		state: diskState{
			Recipes:  map[string]storedRecipe{},
			Batches:  map[string]*batchRecord{},
			Requests: map[string]string{},
		},
	}
	data, err := os.ReadFile(l.path)
	switch {
	case errors.Is(err, fs.ErrNotExist):
		return l, nil
	case err != nil:
		return nil, fmt.Errorf("%w: %v", ErrCorruptData, err)
	}
	if err := json.Unmarshal(data, &l.state); err != nil {
		return nil, fmt.Errorf("%w: %v", ErrCorruptData, err)
	}
	if l.state.Recipes == nil {
		l.state.Recipes = map[string]storedRecipe{}
	}
	if l.state.Batches == nil {
		l.state.Batches = map[string]*batchRecord{}
	}
	if l.state.Requests == nil {
		l.state.Requests = map[string]string{}
	}
	return l, nil
}

// persistLocked 将台账原子写回磁盘：先写临时文件再改名，避免半截文件。
func (l *Ledger) persistLocked() error {
	data, err := json.MarshalIndent(l.state, "", "  ")
	if err != nil {
		return fmt.Errorf("%w: 序列化台账失败: %v", ErrCorruptData, err)
	}
	tmp, err := os.CreateTemp(l.dir, "ledger-*.tmp")
	if err != nil {
		return fmt.Errorf("%w: 写入台账失败: %v", ErrCorruptData, err)
	}
	tmpName := tmp.Name()
	if _, err := tmp.Write(data); err != nil {
		tmp.Close()
		os.Remove(tmpName)
		return fmt.Errorf("%w: 写入台账失败: %v", ErrCorruptData, err)
	}
	if err := tmp.Sync(); err != nil {
		tmp.Close()
		os.Remove(tmpName)
		return fmt.Errorf("%w: 写入台账失败: %v", ErrCorruptData, err)
	}
	if err := tmp.Close(); err != nil {
		os.Remove(tmpName)
		return fmt.Errorf("%w: 写入台账失败: %v", ErrCorruptData, err)
	}
	if err := os.Rename(tmpName, l.path); err != nil {
		os.Remove(tmpName)
		return fmt.Errorf("%w: 写入台账失败: %v", ErrCorruptData, err)
	}
	return nil
}

// fingerprint 计算一次写入操作的规范内容指纹（操作名 + 全部参数）。
func fingerprint(op string, body any) string {
	b, _ := json.Marshal(struct {
		Op   string `json:"op"`
		Body any    `json:"body"`
	}{Op: op, Body: body})
	return string(b)
}

// apply 串行执行一次写入：处理请求编号幂等，成功后持久化。
// fn 返回错误时本次失败不占用请求编号，也不留下任何状态变化。
func (l *Ledger) apply(reqID, fp string, fn func() error) error {
	if reqID == "" {
		return fmt.Errorf("%w: 请求编号不能为空", ErrInvalidInput)
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	if prev, ok := l.state.Requests[reqID]; ok {
		if prev == fp {
			return nil // 同一编号相同内容：返回第一次成功的结果
		}
		return fmt.Errorf("%w: 请求编号 %q", ErrRequestConflict, reqID)
	}
	if err := fn(); err != nil {
		return err
	}
	l.state.Requests[reqID] = fp
	if err := l.persistLocked(); err != nil {
		delete(l.state.Requests, reqID)
		return err
	}
	return nil
}

func validateRecipe(rv RecipeVersion) error {
	if rv.RecipeID == "" || rv.Version == "" || rv.Name == "" {
		return fmt.Errorf("%w: 配方编号、版本号和名称不能为空", ErrInvalidInput)
	}
	if len(rv.Materials) == 0 {
		return fmt.Errorf("%w: 配方版本至少包含一种物料", ErrInvalidInput)
	}
	seen := make(map[string]bool, len(rv.Materials))
	for _, m := range rv.Materials {
		if m.MaterialID == "" {
			return fmt.Errorf("%w: 物料编号不能为空", ErrInvalidInput)
		}
		if seen[m.MaterialID] {
			return fmt.Errorf("%w: %s", ErrDuplicateMaterial, m.MaterialID)
		}
		seen[m.MaterialID] = true
		if m.Grams <= 0 {
			return fmt.Errorf("%w: 物料 %s 的克数必须为正数且最多三位小数", ErrInvalidQuantity, m.MaterialID)
		}
	}
	return nil
}

// RegisterRecipe 登记一个配方版本。同一配方编号和版本号已登记时返回
// ErrRecipeExists，已登记内容不可覆盖。
func (l *Ledger) RegisterRecipe(reqID string, rv RecipeVersion) error {
	fp := fingerprint("register-recipe", rv)
	return l.apply(reqID, fp, func() error {
		if err := validateRecipe(rv); err != nil {
			return err
		}
		key := recipeKey(rv.RecipeID, rv.Version)
		if _, ok := l.state.Recipes[key]; ok {
			return fmt.Errorf("%w: 配方 %s 版本 %s", ErrRecipeExists, rv.RecipeID, rv.Version)
		}
		mats := make([]storedMaterial, len(rv.Materials))
		for i, m := range rv.Materials {
			mats[i] = storedMaterial{MaterialID: m.MaterialID, Milligrams: int64(m.Grams)}
		}
		l.state.Recipes[key] = storedRecipe{
			RecipeID:  rv.RecipeID,
			Version:   rv.Version,
			Name:      rv.Name,
			Materials: mats,
		}
		return nil
	})
}

// GetRecipe 查询已登记的配方版本，返回副本。
func (l *Ledger) GetRecipe(recipeID, version string) (RecipeVersion, error) {
	l.mu.Lock()
	defer l.mu.Unlock()
	r, ok := l.state.Recipes[recipeKey(recipeID, version)]
	if !ok {
		return RecipeVersion{}, fmt.Errorf("%w: 配方 %s 版本 %s", ErrRecipeNotFound, recipeID, version)
	}
	rv := RecipeVersion{
		RecipeID:  r.RecipeID,
		Version:   r.Version,
		Name:      r.Name,
		Materials: make([]Material, len(r.Materials)),
	}
	for i, m := range r.Materials {
		rv.Materials[i] = Material{MaterialID: m.MaterialID, Grams: Grams(m.Milligrams)}
	}
	return rv, nil
}

func (l *Ledger) mustBatch(batchID string) (*batchRecord, error) {
	b, ok := l.state.Batches[batchID]
	if !ok {
		return nil, fmt.Errorf("%w: 批次 %s", ErrNotFound, batchID)
	}
	return b, nil
}

func (l *Ledger) checkRecipeAndUnits(recipeID, version string, units int) error {
	if units <= 0 {
		return fmt.Errorf("%w: 计划份数必须为正整数，得到 %d", ErrInvalidQuantity, units)
	}
	if _, ok := l.state.Recipes[recipeKey(recipeID, version)]; !ok {
		return fmt.Errorf("%w: 配方 %s 版本 %s", ErrRecipeNotFound, recipeID, version)
	}
	return nil
}

// CreateBatch 以独立批次编号建立草稿批次，绑定已登记的配方版本和计划份数。
func (l *Ledger) CreateBatch(reqID, batchID, recipeID, version string, units int) error {
	fp := fingerprint("create-batch", struct {
		BatchID  string `json:"batchId"`
		RecipeID string `json:"recipeId"`
		Version  string `json:"version"`
		Units    int    `json:"units"`
	}{batchID, recipeID, version, units})
	return l.apply(reqID, fp, func() error {
		if batchID == "" {
			return fmt.Errorf("%w: 批次编号不能为空", ErrInvalidInput)
		}
		if _, ok := l.state.Batches[batchID]; ok {
			return fmt.Errorf("%w: %s", ErrBatchExists, batchID)
		}
		if err := l.checkRecipeAndUnits(recipeID, version, units); err != nil {
			return err
		}
		l.state.Batches[batchID] = &batchRecord{
			BatchID:  batchID,
			RecipeID: recipeID,
			Version:  version,
			Units:    units,
			Status:   StatusDraft,
		}
		return nil
	})
}

// UpdateDraft 调整草稿批次的计划份数或改选配方版本。只有草稿可以调整。
func (l *Ledger) UpdateDraft(reqID, batchID, recipeID, version string, units int) error {
	fp := fingerprint("update-draft", struct {
		BatchID  string `json:"batchId"`
		RecipeID string `json:"recipeId"`
		Version  string `json:"version"`
		Units    int    `json:"units"`
	}{batchID, recipeID, version, units})
	return l.apply(reqID, fp, func() error {
		b, err := l.mustBatch(batchID)
		if err != nil {
			return err
		}
		if b.Status != StatusDraft {
			return fmt.Errorf("%w: 批次 %s 已开始执行，计划份数和配方版本已固定", ErrInvalidState, batchID)
		}
		if err := l.checkRecipeAndUnits(recipeID, version, units); err != nil {
			return err
		}
		b.RecipeID, b.Version, b.Units = recipeID, version, units
		return nil
	})
}

// StartBatch 开始执行草稿批次，此后计划份数和配方版本固定。
func (l *Ledger) StartBatch(reqID, batchID string) error {
	fp := fingerprint("start-batch", batchID)
	return l.apply(reqID, fp, func() error {
		b, err := l.mustBatch(batchID)
		if err != nil {
			return err
		}
		if b.Status != StatusDraft {
			return fmt.Errorf("%w: 批次 %s 当前状态为 %s，不能开始执行", ErrInvalidState, batchID, b.Status)
		}
		b.Status = StatusRunning
		return nil
	})
}

// AddFeeding 为执行中的批次追加一条投料。允许不足或超过应投量，
// 已登记的投料不可修改或删除。
func (l *Ledger) AddFeeding(reqID, batchID, materialID string, grams Grams, fedAt time.Time, operator string) error {
	fp := fingerprint("add-feeding", struct {
		BatchID    string    `json:"batchId"`
		MaterialID string    `json:"materialId"`
		Milligrams int64     `json:"milligrams"`
		FedAt      time.Time `json:"fedAt"`
		Operator   string    `json:"operator"`
	}{batchID, materialID, int64(grams), fedAt, operator})
	return l.apply(reqID, fp, func() error {
		b, err := l.mustBatch(batchID)
		if err != nil {
			return err
		}
		if b.Status != StatusRunning {
			return fmt.Errorf("%w: 批次 %s 当前状态为 %s，不能追加投料", ErrInvalidState, batchID, b.Status)
		}
		if grams <= 0 {
			return fmt.Errorf("%w: 投料克数必须为正数且最多三位小数", ErrInvalidQuantity)
		}
		if materialID == "" || operator == "" || fedAt.IsZero() {
			return fmt.Errorf("%w: 物料编号、登记人和投料时间不能为空", ErrInvalidInput)
		}
		r := l.state.Recipes[recipeKey(b.RecipeID, b.Version)]
		found := false
		for _, m := range r.Materials {
			if m.MaterialID == materialID {
				found = true
				break
			}
		}
		if !found {
			return fmt.Errorf("%w: %s", ErrUnknownMaterial, materialID)
		}
		b.Feedings = append(b.Feedings, feedingRecord{
			MaterialID: materialID,
			Milligrams: int64(grams),
			FedAt:      fedAt,
			Operator:   operator,
		})
		return nil
	})
}

// CloseBatch 关闭执行中的批次，确认已有投料（不要求数量吻合）。
// 关闭后不能追加投料，也不能重新打开。
func (l *Ledger) CloseBatch(reqID, batchID string) error {
	fp := fingerprint("close-batch", batchID)
	return l.apply(reqID, fp, func() error {
		b, err := l.mustBatch(batchID)
		if err != nil {
			return err
		}
		if b.Status != StatusRunning {
			return fmt.Errorf("%w: 批次 %s 当前状态为 %s，只有执行中的批次可以关闭", ErrInvalidState, batchID, b.Status)
		}
		b.Status = StatusClosed
		return nil
	})
}

// GetBatch 按批次查询完整记录。投料按成功登记的先后顺序返回，
// 配方中所有物料都列出数量核对；返回的是副本，调用方修改不影响台账。
func (l *Ledger) GetBatch(batchID string) (BatchReport, error) {
	l.mu.Lock()
	defer l.mu.Unlock()
	b, ok := l.state.Batches[batchID]
	if !ok {
		return BatchReport{}, fmt.Errorf("%w: 批次 %s", ErrNotFound, batchID)
	}
	r := l.state.Recipes[recipeKey(b.RecipeID, b.Version)]
	rep := BatchReport{
		BatchID:    b.BatchID,
		RecipeID:   b.RecipeID,
		Version:    b.Version,
		RecipeName: r.Name,
		Units:      b.Units,
		Status:     b.Status,
		Feedings:   make([]Feeding, len(b.Feedings)),
		Materials:  make([]MaterialReport, len(r.Materials)),
	}
	actual := make(map[string]int64, len(r.Materials))
	for i, f := range b.Feedings {
		rep.Feedings[i] = Feeding{
			MaterialID: f.MaterialID,
			Grams:      Grams(f.Milligrams),
			FedAt:      f.FedAt,
			Operator:   f.Operator,
		}
		actual[f.MaterialID] += f.Milligrams
	}
	for i, m := range r.Materials {
		required := m.Milligrams * int64(b.Units)
		act := actual[m.MaterialID]
		rep.Materials[i] = MaterialReport{
			MaterialID: m.MaterialID,
			Required:   Grams(required),
			Actual:     Grams(act),
			Diff:       Grams(act - required),
		}
	}
	return rep, nil
}

