func sampleRecipe(t *testing.T) RecipeVersion {
	t.Helper()
	return RecipeVersion{
		RecipeID: "R-1",
		Version:  "v1",
		Name:     "标准配方",
		Materials: []Material{
			{MaterialID: "M-A", Grams: mustGrams(t, "2.5")},
			{MaterialID: "M-B", Grams: mustGrams(t, "0.125")},
		},
	}
}

func registerSample(t *testing.T, l *Ledger) {
	t.Helper()
